    /**
     *
     * @returns sendId of packet (can be used to identify packet when exception event occurs)
     *
     * @remarks
     * Listen for {@link SimConnectRecvEvents.simObjectData} to get the data.
     *
     * @example
     * ```ts
     * const LIVE_DATA_REQ_ID = 1234;
     *
     * handle.addToDataDefinition(
     *   LIVE_DATA_REQ_ID,
     *   'STRUCT LATLONALT',
     *   null,
     *   SimConnectDataType.LATLONALT
     * );
     *
     * handle.on('simObjectData', recvSimObjectData => {
     *   if (recvSimObjectData.requestID === LIVE_DATA_REQ_ID) {
     *     console.log(readLatLonAlt(recvSimObjectData.data));
     *   }
     * });
     * ```
     */
    requestDataOnSimObject(
        dataRequestId: DataRequestId,
        dataDefinitionId: DataDefinitionId,
        objectId: ObjectId,
        period: SimConnectPeriod,
        flags?: DataRequestFlag,
        origin?: number,
        interval?: number,
        limit?: number
    ): number {
        return this._buildAndSend(
            this._beginPacket(0x0e)
                .putUint32(dataRequestId)
                .putUint32(dataDefinitionId)
                .putUint32(objectId)
                .putUint32(period)
                .putUint32(flags || 0)
                .putUint32(origin || 0)
                .putUint32(interval || 0)
                .putUint32(limit || 0)
        );
    }

    /**
     *
     * @returns sendId of packet (can be used to identify packet when exception event occurs)
     *
     * @remarks
     * Listen for {@link SimConnectRecvEvents.simObjectDataByType} to get the data.
     *
     */
    requestDataOnSimObjectType(
        dataRequestId: DataRequestId,
        dataDefinitionId: DataDefinitionId,
        radiusMeters: number,
        type: SimObjectType
    ): number {
        return this._buildAndSend(
            this._beginPacket(0x0f)
                .putUint32(dataRequestId)
                .putUint32(dataDefinitionId)
                .putUint32(radiusMeters)
                .putUint32(type)
        );
    }

    /**
     *
     * @returns sendId of packet (can be used to identify packet when exception event occurs)
     */
    setDataOnSimObject(
        dataDefinitionId: DataDefinitionId,
        objectId: ObjectId,
        data: { buffer: RawBuffer; arrayCount: number; tagged: boolean } | SimConnectData[]
    ): number {
        const packet = this._beginPacket(0x10) //
            .putUint32(dataDefinitionId)
            .putUint32(objectId);

        if (data instanceof Array) {
            packet
                .putUint32(DataSetFlag.DEFAULT) //
                .putUint32(data.length) //
                .putUint32(0); // Just a placeholder for array unit size

            const arrayStartPos = packet.getRawBuffer().getOffset();

            data.forEach(simConnectData => {
                simConnectData.writeTo(packet);
            });

            const arrayTotalSize = packet.getRawBuffer().getOffset() - arrayStartPos;
            const unitSize = arrayTotalSize / data.length;
            packet.putUint32(unitSize, arrayStartPos - 4); // Replace placeholder
        } else {
            const { tagged, arrayCount, buffer } = data;
            const bytes = buffer.getBuffer();
            packet
                .putUint32(tagged ? DataSetFlag.TAGGED : DataSetFlag.DEFAULT)
                .putUint32(arrayCount === 0 ? 1 : arrayCount)
                .putUint32(bytes.length)
                .putBytes(bytes);
        }

        return this._buildAndSend(packet);
    }

